#include <string>
#include <vector>
#include <map>
#include <chrono>
#include <mutex>
#include <functional>
#include <algorithm>
#include <cstring>

namespace iot_auth {

enum class CircuitState { CLOSED, OPEN, HALF_OPEN };

struct CircuitBreaker {
    CircuitState state = CircuitState::CLOSED;
    int failure_count = 0;
    int success_count = 0;
    static constexpr int FAILURE_THRESHOLD = 5;
    static constexpr int SUCCESS_THRESHOLD = 3;
    std::chrono::steady_clock::time_point last_failure;
    std::chrono::seconds cooldown{30};
    std::mutex mtx;

    bool allow_request() {
        std::lock_guard<std::mutex> lock(mtx);
        if (state == CircuitState::CLOSED) return true;
        if (state == CircuitState::OPEN) {
            auto now = std::chrono::steady_clock::now();
            if (now - last_failure > cooldown) {
                state = CircuitState::HALF_OPEN;
                return true;
            }
            return false;
        }
        return true; // HALF_OPEN allows probe requests
    }

    void record_success() {
        std::lock_guard<std::mutex> lock(mtx);
        if (state == CircuitState::HALF_OPEN) {
            success_count++;
            if (success_count >= SUCCESS_THRESHOLD) {
                state = CircuitState::CLOSED;
                failure_count = 0;
                success_count = 0;
            }
        }
    }

    void record_failure() {
        std::lock_guard<std::mutex> lock(mtx);
        failure_count++;
        last_failure = std::chrono::steady_clock::now();
        if (failure_count >= FAILURE_THRESHOLD) {
            state = CircuitState::OPEN;
            success_count = 0;
        }
    }
};

struct OAuthConfig {
    std::string client_id;
    std::string auth_endpoint;
    std::vector<std::string> allowed_redirect_origins;
    std::string device_id;
};

class RedirectValidator {
private:
    OAuthConfig config_;
    CircuitBreaker breaker_;

    // Normalize URI by resolving percent-encoding and path traversal
    std::string normalize_uri(const std::string& uri) const {
        std::string result;
        result.reserve(uri.size());
        for (size_t i = 0; i < uri.size(); i++) {
            if (uri[i] == '%' && i + 2 < uri.size()) {
                char high = uri[i+1];
                char low = uri[i+2];
                auto hex_val = [](char c) -> int {
                    if (c >= '0' && c <= '9') return c - '0';
                    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
                    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
                    return -1;
                };
                int h = hex_val(high), l = hex_val(low);
                if (h >= 0 && l >= 0) {
                    result += static_cast<char>((h << 4) | l);
                    i += 2;
                } else {
                    result += uri[i];
                }
            } else {
                result += uri[i];
            }
        }
        return result;
    }

    // Extract origin (scheme + host + port) from a URI
    std::string extract_origin(const std::string& uri) const {
        size_t scheme_end = uri.find("://");
        if (scheme_end == std::string::npos) return "";
        size_t authority_start = scheme_end + 3;
        size_t authority_end = uri.find('/', authority_start);
        if (authority_end == std::string::npos) authority_end = uri.size();
        // Also check for query/fragment before path
        size_t query_pos = uri.find('?', authority_start);
        size_t frag_pos = uri.find('#', authority_start);
        authority_end = std::min({authority_end, query_pos, frag_pos});
        return uri.substr(0, authority_end);
    }

    // Check if redirect_uri origin matches any allowed origin
    bool origin_matches(const std::string& normalized_uri) const {
        std::string origin = extract_origin(normalized_uri);
        // Case-insensitive comparison for origin matching
        std::string lower_origin = origin;
        std::transform(lower_origin.begin(), lower_origin.end(),
                      lower_origin.begin(), ::tolower);
        for (const auto& allowed : config_.allowed_redirect_origins) {
            std::string lower_allowed = allowed;
            std::transform(lower_allowed.begin(), lower_allowed.end(),
                          lower_allowed.begin(), ::tolower);
            if (lower_origin == lower_allowed) return true;
            // Subdomain matching: allow *.example.com
            if (lower_allowed.substr(0, 4) == "http") {
                std::string allowed_host = extract_origin(lower_allowed);
                size_t at_scheme = allowed_host.find("://");
                if (at_scheme != std::string::npos) {
                    std::string allowed_domain = allowed_host.substr(at_scheme + 3);
                    size_t orig_scheme = lower_origin.find("://");
                    if (orig_scheme != std::string::npos) {
                        std::string orig_domain = lower_origin.substr(orig_scheme + 3);
                        // Check if origin domain ends with allowed domain
                        if (orig_domain.size() >= allowed_domain.size()) {
                            size_t offset = orig_domain.size() - allowed_domain.size();
                            if (orig_domain.substr(offset) == allowed_domain) {
                                // Ensure it's a proper subdomain boundary
                                if (offset == 0 || orig_domain[offset - 1] == '.') {
                                    return true;
                                }
                            }
                        }
                    }
                }
            }
        }
        return false;
    }

public:
    RedirectValidator(const OAuthConfig& config) : config_(config) {}

    // Validate redirect URI with circuit breaker protection
    bool validate_redirect(const std::string& redirect_uri) {
        if (!breaker_.allow_request()) {
            return false; // Circuit open, reject all
        }

        std::string normalized = normalize_uri(redirect_uri);

        // Security check: reject URIs with embedded credentials
        if (normalized.find('@') != std::string::npos) {
            size_t scheme_end = normalized.find("://");
            size_t at_pos = normalized.find('@');
            if (scheme_end != std::string::npos && at_pos > scheme_end) {
                breaker_.record_failure();
                return false;
            }
        }

        // Validate the origin
        if (origin_matches(normalized)) {
            breaker_.record_success();
            return true;
        }

        breaker_.record_failure();
        return false;
    }

    CircuitState get_circuit_state() const {
        return breaker_.state;
    }
};

// Device firmware OAuth handler
class DeviceOAuthHandler {
private:
    RedirectValidator validator_;
    std::string pending_state_;

public:
    DeviceOAuthHandler(const OAuthConfig& config) : validator_(config) {}

    struct AuthResponse {
        bool success;
        std::string redirect_location;
        std::string error;
    };

    AuthResponse initiate_auth(const std::string& redirect_uri,
                               const std::string& state) {
        AuthResponse resp{};

        if (redirect_uri.empty()) {
            resp.error = "missing_redirect_uri";
            return resp;
        }

        if (!validator_.validate_redirect(redirect_uri)) {
            resp.error = "invalid_redirect_uri";
            return resp;
        }

        pending_state_ = state;
        resp.success = true;
        resp.redirect_location = redirect_uri + "?code=AUTH_CODE&state=" + state;
        return resp;
    }
};

} // namespace iot_auth
